"""Render measured reports only after every required automated gate has completed."""
import argparse,json,re,hashlib
from pathlib import Path

def main():
 ap=argparse.ArgumentParser();ap.add_argument('validation',type=Path);ap.add_argument('campaign_summary',type=Path);ap.add_argument('--output',type=Path,required=True);a=ap.parse_args();reports=a.validation/'reports';a.output.mkdir(parents=True,exist_ok=True)
 names=['cinematic','stability','compatibility','production','bridge','mobile_functional','migrate_phase1','migrate_phase2','migrate_phase3','migrate_phase3_30','static','performance','campaign_patch_scope'];tests={n:json.loads((reports/(n+'.json')).read_text()) for n in names};assert all(r['passed'] for r in tests.values()),[n for n,r in tests.items() if not r['passed']]
 node=(reports/'node.txt').read_text();assert re.search(r'fail 0\b',node) and re.search(r'skipped 0\b',node);count=int(re.search(r'tests (\d+)',node)[1]);campaigns=json.loads(a.campaign_summary.read_text());assert campaigns['passed'];manifest=json.loads((a.validation/'tested/ICARUS_Cinematic_Living_World_Phase3_Lite/BUILD_MANIFEST.json').read_text());assert all(v['runtime_sha256']==campaigns['campaigns']['normal_1001']['runtime_sha256'] for v in campaigns['campaigns'].values())
 missing=['Native Windows BAT/input','Physical Android/Wi-Fi and Galaxy Tab S5e/Samsung TV','Firefox/Safari','Antivirus engine/penetration testing','Human long-form story quality, final art/audio and accessibility review']
 accepted={'runtime_source_commit':manifest['source_commit'],'runtime_files':manifest['runtime_files'],'unit_tests':{'passed':count,'failed':0,'skipped':0},'tests':tests,'campaigns':campaigns['campaigns'],'campaign_scope':'Campaigns began at 65403c0. Final runtime differs only by idempotent group initialization in restoreBackup, exactly verified in campaign_patch_scope; no physical simulation/calendar changes. Ordinary runs checkpoint-reload at days 7/30; adverse runs complete day 7. This is not a claim that every campaign began at the final packaging commit.','not_run':missing,'passed':True,'full_phase3_complete':False};(a.output/'accepted_summary.json').write_text(json.dumps(accepted,indent=2))
 lines=['# Phase 3 measured validation','', 'Status: substantial working increment verified within the explicit limits below. **Full Phase 3/final audiovisual production is not declared complete.** See PHASE3_LIMITATIONS.md and FINAL_RELEASE_ROADMAP.md.','',f'Runtime tested from **{manifest["source_commit"]}** through an independently extracted source-based Lite ZIP, with **55 runtime files**. Final packaging may update documentation; runtime hashes must stay identical. Long campaigns began at 65403c0; the later isolated backup-import fix only initializes missing optional groups. An exact string reconstruction verifies that patch scope and all 54 other runtime files match; physical ticks/calendar are unchanged. Campaign source hashes are retained rather than rewritten.','', '## Final extracted Lite automated results','', '| Suite | Actual result |','| --- | --- |',f'| Node deterministic cases | {count} passed, 0 failed, 0 skipped |']
 for n in ['cinematic','stability','compatibility','production','bridge']:lines.append(f'| {n} Chromium suite | {tests[n]["tests_run"]} passed |')
 lines+=['| Pixel 5 touch/mobile flow | '+str(len(tests['mobile_functional']['checks']))+' checks passed; actual HTTP, stubbed host input/TV |',f'| Static/dependency/manifest | {tests["static"]["syntax_files"]} syntax files; {tests["static"]["local_scripts"]} local script dependencies; all retained hashes verified |','','Browser suites overlap inherited cases; counts are executions, not distinct scenarios. Tests run outside Lite against extracted assets. Positive extraordinary-lethal tests use explicitly authored fixtures, not claimed natural campaign clips.','', '## Real backup migration','', '| Backup | History records in receiving browser | Tick resumed | Result |','| --- | --- | --- | --- |']
 for n in ['migrate_phase1','migrate_phase2','migrate_phase3','migrate_phase3_30']:
  r=tests[n];lines.append(f'| {n} | {r["imported_history_records"]} | {r["imported_tick"]} → {r["resumed_tick"]} | Original compared domains, full history IDs and exact reload preserved |')
 lines+=['','The original Phase 1/2 imports exposed missing immediate Phase 3 group initialization; those earlier reload comparisons failed. The restore-path correction and explicit old-backup regression repair that defect. No assertion was weakened. Historical archive-ID additions are checked against actual acquired SOL sources.','', '## Continuous campaigns','', 'Fixed start 2026-10-28 00:00 UTC, America/Chicago. Production physical/calendar controllers process hourly real intervals; test-driver per-step autosave is disabled, actual saves/checkpoint reloads asserted. Thirty real days equal 111.75 simulated days due to synchronized 1× holidays; seven equal 25.0. Adverse initial states use asserted normal backup-import fixtures, not natural-event claims.','', '| Profile | Real / simulated days | Alive / dead | Arrivals | Field / local jobs | Conversations | Films |','| --- | --- | --- | --- | --- | --- | --- |']
 for name,r in campaigns['campaigns'].items():lines.append(f'| {name} | {r["real_days"]} / {r["sim_days"]} | {r["alive"]} / {len(r["dead"])} | {r["arrivals"]} | {r["field_missions"]} / {r["local_jobs"]} | {r["conversations"]} | {r["weekly_films"]} |')
 lines+=['','Daily resource/frontier/chronicle/knowledge/creature/cinematic audits pass, all original crew identities remain accounted for, wall time is not discarded/rewound and checkpoint reloads match. Independent full-history audits find no private/missing public film/SOL sources or invalid snapshot provenance. Real travel/objectives are required; survival alone is insufficient.','', 'Ordinary seed 4807 records Nadia’s existing egg exposure, uncertain delivered debrief, 240-minute host development, death and preserved memorial. PHASE3_CAMPAIGN_EVENTS.md gives actual source IDs and UTC/ticks. No survival guarantee or manufactured Legendary segment was added.','', '## Sources, science, resources and growth','']
 for name,r in campaigns['campaigns'].items():
  lines.append(f'- **{name}:** {r["history_records"]} full history records; {r["science_cases"]} science cases; experiment statuses {json.dumps(r["experiment_statuses"],sort_keys=True)}; {r["captured_state_frames"]} actual captured state frames, {r["retained_visual_frames"]} retained; {r["film_recorded_segments"]} sourced recorded film segments, {r["film_legendary_segments"]} Legendary segments. Film durations: {r["film_durations_seconds"]} seconds. Primary compressed cache: {r["storage_first"]["primary_bytes"]} → {r["storage_last"]["primary_bytes"]} bytes. Travel fuel: {r["travel_fuel"]}.')
 lines+=['','Complete resource balances/acquisition, source-kind diversity, repeated social text counts, checkpoints, fatality causal windows and runtime/backup SHA-256 values are in reports/phase3/campaign_summary.json and accepted_summary.json. Resource audits retain finite production/conversion/consumption/transfer identities; Phase 3 adds no free-resource source. Sparse frames mean reconstruction cards are common. Short quiet archives are intentional, not filled with invented scenes.','', '## Performance and unavailable gates','']
 p=tests['performance'];lines.append(f'{p["samples"]} paused synchronous camera refreshes: mean {p["mean_ms"]:.3f} ms, p95 {p["p95_ms"]:.3f} ms, max {p["max_ms"]:.3f} ms. Actor rebuild counter {p["before"]["actorRebuilds"]} → {p["after"]["actorRebuilds"]}; world snapshot unchanged. Heap samples and Linux campaign RSS series are retained separately. Timings under concurrent headless load are not native GPU/compositor FPS or a proof of no multi-year leak.')
 memory=json.loads((reports/'campaign_memory.json').read_text());peaks={}
 for sample in memory['samples']:
  for name,v in sample['campaigns'].items():peaks[name]=max(peaks.get(name,0),v['sum_rss_kib'])
 lines+=['', 'Linux campaign process-tree RSS peaks (MiB): '+', '.join(name.split('--output ')[-1].split('/')[-1]+' '+str(round(value/1024,1)) for name,value in peaks.items())+'. This includes Python harness, browser and shared pages counted more than once; it is not retained game JS heap or Android thin-client memory. Full timestamp samples are retained.', '']
 lines+=['','Routine memories 24/person, choices 12/person, snapshots 120, SOL notes 48 and films 12 weeks are bounded; full history/knowledge still grow. Archival streaming and single-writer coordination remain open.','', 'Not run: '+ '; '.join(missing)+'. No antivirus bypass or native-hardware certification is implied.','', 'Superseded diagnostic failures/campaigns are identified in engineering notes and excluded from accepted totals. Smaller complete presentation features ship now; richer awards, automatic exceptional-encounter classification/capture, final audiovisual production and human review remain incomplete. Next batch: human-led editorial/UI refinement and save-streaming/single-writer hardening before additional scope.']
 Path('PHASE3_VALIDATION.md').write_text('\n'.join(lines)+'\n');print('Accepted automated increment; full Phase 3 remains incomplete by stated limits.')
if __name__=='__main__':main()
